import sys

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    s = input[1]

    for i in range(n - 1):
        if s[i] > s[i + 1]:
            print("YES")
            print(i + 1, i + 2)
            return

    for i in range(n - 1):
        for j in range(i + 1, n):
            reversed_substring = s[:i] + s[j:i-1:-1] + s[j+1:]
            if reversed_substring < s:
                print("YES")
                print(i + 1, j + 1)
                return

    print("NO")

if __name__ == "__main__":
    main()
